+static vec4 c6_sample(GLuint tex, float u, float v) {
+    if (!tex) return vec4{0.f, 0.f, 0.f, 1.f};
+    return texture2D(tex, u, v);
+}
+
+static void c6_vs(float* vs_output, vec4* vertex_attribs,
+                  Shader_Builtins* builtins, void* uniforms) {
+    C6Uniforms* u = (C6Uniforms*)uniforms;
+    vec4 pos = u->apos >= 0 ? vertex_attribs[u->apos] : vec4{0.f, 0.f, 0.f, 1.f};
+    vec4 col = u->acol >= 0 ? vertex_attribs[u->acol] : vec4{0.f, 0.f, 0.f, 1.f};
+    vec4 uv;
+    if (u->uv_identity) {
+        // [C6-UVFIX]: the canonical fullscreen-quad identity — the uv stream
+        // aliases the position store, so synthesize uv = pos*0.5+0.5 from the
+        // live position data (-1..1 → 0..1) instead of sampling the aliased
+        // (out-of-domain) stream.
+        uv = vec4{pos.x * 0.5f + 0.5f, pos.y * 0.5f + 0.5f, 0.f, 0.f};
+    } else {
+        uv = u->auv >= 0 ? vertex_attribs[u->auv] : vec4{0.f, 0.f, 0.f, 0.f};
+    }
+    ((vec4*)vs_output)[0] = col;
+    ((vec4*)vs_output)[1] = uv;
+    builtins->gl_Position = mult_m4_v4((float(&)[16])u->proj, pos);
