+
+static void c6_fs(float* fs_input, Shader_Builtins* builtins, void* uniforms) {
+    C6Uniforms* u = (C6Uniforms*)uniforms;
+    vec4 col = ((vec4*)fs_input)[0];
+    vec4 uv4 = ((vec4*)fs_input)[1];
+    vec4 t = c6_sample(u->tex0, uv4.x, uv4.y);
+    vec4 out;
+    if (u->mode == 2) {
+        vec4 b = c6_sample(u->tex1, uv4.x, uv4.y);
+        out = vec4{ t.x * u->orig_i + b.x * u->bloom_i,
+                    t.y * u->orig_i + b.y * u->bloom_i,
+                    t.z * u->orig_i + b.z * u->bloom_i,
+                    t.w * u->orig_i + b.w * u->bloom_i };
+    } else if (u->mode == 1) {
+        // C6-R8c single-texture BLIT: NO color multiply (the raw screenspace
+        // blit contract — multiplying by the disabled-slot color collapsed
+        // the window blit to black).
+        out = t;
+    } else {
+        out = vec4{ t.x * col.x, t.y * col.y, t.z * col.z, t.w * col.w };
+    }
