+bool GLES20Bridge::read_texture(uint32_t tex_id, std::vector<uint32_t>& px,
+                                int& w, int& h) {
+    // PGL RT memory FIRST: FBO renders write the texture through PGL's
+    // framebuffer path (never through glTexImage2D), so the bridge-side
+    // registry copy goes stale after any render-to-texture. The reader
+    // (pgl_backend.cpp) reads the REAL PGL texture memory.
+    if (pgl_read_texture(tex_id, px, w, h)) return true;
+    auto it = textures_.find(tex_id);
+    if (it == textures_.end() || !it->second.live || it->second.rgba.empty())
+        return false;
+    px = it->second.rgba;
+    w = it->second.w;
+    h = it->second.h;
+    return true;
+}
