+// ── [C6-FBOTRUTH] P0-3 law-2 ground truth: per-FBO draw histogram +
+// attachment content stats, straight from the real stores. Env-gated
+// (MINIANDROID_FB0_TRACE); at most two dumps per tag per run.
+// Answers: (a) which FBO the app's draws land in (draws / sum_cnt /
+// max_cnt), (b) what every FBO attachment holds post-pass (uniform?
+// clear color? sentinel? content?) — the scene-FBO black face is decided
+// by these facts, not inference.
+void GLES20Bridge::dump_fbo_truth(const char* tag) {
+    static thread_local const bool on =
+        std::getenv("MINIANDROID_FB0_TRACE") != nullptr;
+    if (!on) return;
+    static thread_local std::map<std::string, int> done;
+    if (done[tag]++ >= 2) return;
+    std::cerr << "[C6-FBOTRUTH] --- " << tag << " ---" << std::endl;
+    for (const auto& [fbo, st] : fbo_draw_stats_)
+        std::cerr << "[C6-FBODRAW] " << tag << " fbo=" << fbo
+                  << " draws=" << st.draws << " sum_cnt=" << st.sum_cnt
+                  << " max_cnt=" << st.max_cnt << std::endl;
+    for (const auto& [fbo, rec] : fbos_) {
+        if (rec.color_tex == 0) continue;
+        std::vector<uint32_t> px;
+        int w = 0, h = 0;
+        if (!read_texture(rec.color_tex, px, w, h) || px.empty()) {
+            std::cerr << "[C6-ATTSTAT] " << tag << " fbo=" << fbo << " tex="
+                      << rec.color_tex << " UNREADABLE" << std::endl;
+            continue;
+        }
+        const size_t step = std::max((size_t)1, px.size() / 512);
+        size_t nonclear = 0, nonsent = 0, diff = 0;
+        std::map<uint32_t, size_t> hist;
+        const uint32_t p0 = px[0];
+        for (size_t i = 0; i < px.size(); i += step) {
+            ++hist[px[i]];
+            if (px[i] != 0xFF000000u) ++nonclear;
+            if (px[i] != 0xEFBEADDEu) ++nonsent;
+            if (px[i] != p0) ++diff;
+        }
+        std::vector<std::pair<uint32_t, size_t>> top(hist.begin(), hist.end());
+        std::sort(top.begin(), top.end(),
+                  [](auto& a, auto& b) { return a.second > b.second; });
+        auto hx = [](uint32_t v) {
+            char b[9];
+            snprintf(b, sizeof b, "%08x", v);
+            return std::string(b);
+        };
+        std::cerr << "[C6-ATTSTAT] " << tag << " fbo=" << fbo << " tex="
+                  << rec.color_tex << " " << rec.w << "x" << rec.h
+                  << " diff=" << diff << "/" << (px.size() / step)
+                  << " nonclear=" << nonclear << " nonsent=" << nonsent
+                  << " top=[" << hx(top[0].first) << "x" << top[0].second;
+        for (int k = 1; k < 3 && k < (int)top.size(); ++k)
+            std::cerr << ", " << hx(top[k].first) << "x" << top[k].second;
+        std::cerr << "]" << std::endl;
+    }
