+void GLES20Bridge::clone_texture(uint32_t src, uint32_t& dst) {
+    // W6-5: the clone must carry the PRE-DRAW content — read the REAL PGL
+    // texture memory (the registry copy goes stale after RT renders).
+    std::vector<uint32_t> rgba;
+    int w = 0, h = 0;
+    if (!read_texture(src, rgba, w, h)) {
+        dst = 0;
+        return;
+    }
+    GLuint d = 0;
+    glGenTextures(1, &d);
+    if (!d) { dst = 0; return; }
+    GLint prev = (active_unit_ < kUnits) ? (GLint)unit_tex_[active_unit_] : 0;
+    glBindTexture(GL_TEXTURE_2D, d);
+    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_NEAREST);
+    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_NEAREST);
+    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
+    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
+    glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, w, h, 0,
+                 GL_RGBA, GL_UNSIGNED_BYTE, rgba.data());
+    glBindTexture(GL_TEXTURE_2D, prev);
+    TexRec& t = textures_[d];
+    t.w = w; t.h = h; t.live = true;
+    t.rgba = std::move(rgba);  // same pixels in a fresh real PGL texture
+    dst = d;
+}
