+void GLES20Bridge::restage_client_slot(int slot, std::vector<uint8_t>&& bytes,
+                                       size_t pos_bytes) {
+    if (slot < 0 || slot >= 8) return;
+    AttribBacking& ab = attrib_backing_[slot];
+    if (!ab.enabled || ab.vbo_id != 0) return;  // VBO slots live in PGL
+    if (bytes.empty() || pos_bytes > bytes.size()) return;
+    const size_t fresh = bytes.size() - pos_bytes;
+    // [C6-RD] the store is refreshed even when the SIZE is unchanged: the
+    // law's root case is a same-capacity buffer REFILLED between the last
+    // glVertexAttribPointer and the draw (stale CONTENT, not just size).
+    ab.bytes.assign(fresh + 4096, 0);  // +4KiB zero tail (R6f law)
+    std::memcpy(ab.bytes.data(), bytes.data() + pos_bytes, fresh);
+    ab.client_ptr = (uintptr_t)ab.bytes.data();
+    static thread_local uint64_t rd_rows = 0;
+    if (rd_rows++ < 24)
+        std::cerr << "[C6-RD] restage slot#" << slot << " live=" << fresh
+                  << "B pos=" << pos_bytes << std::endl;
+}
