+// ── check bookkeeping ─────────────────────────────────────────────────────
+static int g_checks = 0;
+static int g_fails = 0;
+
+static void check(bool ok, const std::string& name) {
+    ++g_checks;
+    if (!ok) ++g_fails;
+    std::cout << "  [" << (ok ? "PASS" : "FAIL") << "] " << name << "\n";
+}
