+// TEST 40 — ArrayBlockingQueue capacity law (IAE, put-full parks,
+// take frees + wakes the putter, remainingCapacity).
+static void test40_abq(DalvikHeap& heap, ThreadShadow* ts, HandlerShadow* hs,
+                       LocksShadow* ls) {
+    std::cout << "\n[TEST 40] ArrayBlockingQueue capacity law\n";
+    uint32_t bad = heap.allocate(kABQ, 0, 0);
+    CallResult neg = call(ls, kABQ, "<init>", true, bad, {long_arg(0)});
+    check(neg.handled && neg.is_exc,
+          "ArrayBlockingQueue(0) → IllegalArgumentException (JDK law)");
+    uint32_t q = heap.allocate(kABQ, 0, 0);
+    call(ls, kABQ, "<init>", true, q, {long_arg(1)});
+    uint32_t e1 = heap.allocate(kTaskCls, 0, 0);
+    uint32_t e2 = heap.allocate(kTaskCls, 0, 0);
+    call(ls, kABQ, "put", true, q, {obj_arg(e1)});
+    check(call(ls, kABQ, "remainingCapacity", true, q).long_val == 0,
+          "capacity 1, one element → remainingCapacity 0");
+    CallResult off = call(ls, kABQ, "offer", true, q, {obj_arg(e2)});
+    check(off.handled && off.bool_val == false,
+          "offer on FULL → false (immediate form)");
+    // put on FULL parks the producer on the PUT-side wait key.
+    uint32_t producer = heap.allocate(kThread, 0, 0);
+    {
+        IdentityGuard g(ts, producer);
+        uint32_t put_key = LocksShadow::put_wait_key(q);
+        ts->register_wait(producer, put_key, INT64_MAX);
+        ev(ts, hs, "TEST40 producer parked FULL");
+        check(ts->thread_state(producer) ==
+                  ThreadShadow::ThreadState::WAITING,
+              "put-when-full → WAITING on the put-side key");
+        // A take frees capacity and wakes ONE putter.
+        CallResult t = call(ls, kABQ, "take", true, q);
+        check(t.handled && t.object_id == e1, "take → e1");
+        bool intr40 = false, not40 = false;
+        check(ts->consume_wait_resume_result(producer, put_key, &intr40,
+                                             &not40) &&
+                  not40,
+              "take woke the parked PRODUCER (putter, not a taker)");
+        check(ts->waiters_on(put_key) == 0, "put-side wait set empty");
+    }
+    call(ls, kABQ, "put", true, q, {obj_arg(e2)});
+    check(call(ls, kABQ, "size", true, q).long_val == 1, "size == 1 after retry");
+}
