+    q.descs.push_front(element_desc);
+}
+bool LocksShadow::queue_take_back(uint32_t oid, uint32_t& out_element,
+                                  std::string& out_desc) {
+    auto it = queue_states_.find(oid);
+    if (it == queue_states_.end() || it->second.elements.empty()) return false;
+    out_element = it->second.elements.back();
+    out_desc = it->second.descs.back();
+    it->second.elements.pop_back();
+    it->second.descs.pop_back();
+    return true;
+}
