+void LocksShadow::xfer_register_put(uint32_t oid, uint32_t item,
+                                    const std::string& desc) {
+    TransferState& st = transfer_states_[oid];
+    if (st.xfer_pending) return;  // deterministic single-slot (JDK: one
+                                  // unmatched producer per rendezvous)
+    st.xfer_pending = true;
+    st.xfer_item = item;
+    st.xfer_desc = desc;
+}
+bool LocksShadow::xfer_has_pending(uint32_t oid) const {
+    auto it = transfer_states_.find(oid);
+    return it != transfer_states_.end() && it->second.xfer_pending;
+}
+uint32_t LocksShadow::xfer_pending_thread(uint32_t oid) const {
+    auto it = transfer_states_.find(oid);
+    return it != transfer_states_.end() ? it->second.xfer_thread : 0;
+}
+bool LocksShadow::xfer_take(uint32_t oid, uint32_t& out_item,
+                            std::string& out_desc) {
+    TransferState& st = transfer_states_[oid];
+    if (st.xfer_pending) {
+        // The waiting producer's item is delivered FIRST (OpenJDK xfer:
+        // a consumer matches an unmatched producer before the queue).
+        out_item = st.xfer_item;
+        out_desc = st.xfer_desc;
+        st.xfer_pending = false;
+        st.xfer_item = 0;
+        st.xfer_desc.clear();
+        return true;
+    }
+    if (st.elements.empty()) return false;
+    out_item = st.elements.front();
+    out_desc = st.descs.front();
+    st.elements.pop_front();
+    st.descs.pop_front();
+    return true;
+}
+bool LocksShadow::xfer_peek(uint32_t oid, uint32_t& out_item,
+                            std::string& out_desc) const {
+    auto it = transfer_states_.find(oid);
+    if (it == transfer_states_.end()) return false;
+    if (it->second.xfer_pending) {
+        out_item = it->second.xfer_item;
+        out_desc = it->second.xfer_desc;
+        return true;
+    }
+    if (it->second.elements.empty()) return false;
+    out_item = it->second.elements.front();
+    out_desc = it->second.descs.front();
+    return true;
+}
+bool LocksShadow::xfer_enqueue(uint32_t oid, uint32_t item,
+                               const std::string& desc) {
+    TransferState& st = transfer_states_[oid];
+    st.elements.push_back(item);
+    st.descs.push_back(desc);
+    return true;
+}
+size_t LocksShadow::xfer_size(uint32_t oid) const {
+    auto it = transfer_states_.find(oid);
+    if (it == transfer_states_.end()) return 0;
+    return it->second.elements.size() + (it->second.xfer_pending ? 1 : 0);
+}
+bool LocksShadow::xfer_pending(uint32_t oid) const {
+    return xfer_has_pending(oid);
+}
