+void LocksShadow::pbq_add(uint32_t oid, int64_t priority, uint32_t item,
+                          const std::string& desc) {
+    PqEntry e;
+    e.priority = priority;
+    e.item = item;
+    e.desc = desc;
+    e.seq = pq_seq_++;
+    std::vector<PqEntry>& v = pq_states_[oid];
+    auto at = std::upper_bound(
+        v.begin(), v.end(), e, [](const PqEntry& a, const PqEntry& b) {
+            return a.priority != b.priority ? a.priority < b.priority
+                                            : a.seq < b.seq;
+        });
+    v.insert(at, e);
+}
+bool LocksShadow::pbq_peek(uint32_t oid, uint32_t& out_item,
+                           std::string& out_desc) const {
+    auto it = pq_states_.find(oid);
+    if (it == pq_states_.end() || it->second.empty()) return false;
+    out_item = it->second.front().item;
+    out_desc = it->second.front().desc;
+    return true;
+}
+bool LocksShadow::pbq_take(uint32_t oid, uint32_t& out_item,
+                           std::string& out_desc) {
+    auto it = pq_states_.find(oid);
+    if (it == pq_states_.end() || it->second.empty()) return false;
+    out_item = it->second.front().item;
+    out_desc = it->second.front().desc;
+    it->second.erase(it->second.begin());
+    return true;
