+// CountDownLatch / Semaphore / CyclicBarrier / Exchanger / queues.
+CallResult LocksShadow::dispatch_juc_coordinator(const CallContext& ctx) {
+    LocksShadow* self = this;
+    ShadowRegistry* reg = registry_;
+    HeapAllocator* heap = heap_;
+    const std::string& cls = ctx.class_name;
+    const std::string& m = ctx.method;
+    const uint32_t recv = ctx.has_receiver ? ctx.receiver_id : 0;
+
+    // ── CountDownLatch ────────────────────────────────────────────────
+    if (cls == "Ljava/util/concurrent/CountDownLatch;") {
+        if (m == "<init>") {
+            int64_t count = ctx.args.empty() ? 0 : ctx.args[0].long_val;
+            if (count < 0) {
+                std::cerr << "[JUC][LAW] CountDownLatch.<init>(" << count
+                          << ") → IllegalArgumentException (JDK law)"
+                          << std::endl;
+                return juc_iae("count < 0");
+            }
+            self->latch_counts_[recv] = count;
+            std::cerr << "[JUC] CountDownLatch o" << recv
+                      << " ctor count=" << count << std::endl;
+            return juc_void();
+        }
+        if (m == "getCount") return juc_long(self->latch_count(recv));
+        if (m == "countDown") {
+            int64_t next = self->latch_count_down(recv);
+            std::cerr << "[JUC] CountDownLatch o" << recv << " countDown → "
+                      << next << std::endl;
+            return juc_void();
+        }
+        // await()/await(t,u): the ENGINE bridge law parks the caller when
+        // count > 0 (per-monitor wait set on the latch oid) and handles
+        // the timed boolean at re-entry; the shadow's own surface answers
+        // only the already-open case (count == 0 → return immediately).
+        if (m == "await" || m == "awaitJ") {
+            if (self->latch_count(recv) == 0) return juc_void();
+            std::cerr << "[JUC][BOUNDARY] CountDownLatch o" << recv
+                      << " await with count=" << self->latch_count(recv)
+                      << " reached the shadow — park is engine-owned"
+                      << std::endl;
+            return juc_void();
+        }
+        if (m == "toString")
+            return CallResult::handled_string("CountDownLatch[count=" +
+                                              std::to_string(
+                                                  self->latch_count(recv)) +
+                                              "]");
+        return CallResult::not_handled();
+    }
+
+    // ── Semaphore ────────────────────────────────────────────────────
+    if (cls == "Ljava/util/concurrent/Semaphore;") {
+        if (m == "<init>") {
+            int64_t permits = ctx.args.empty() ? 0 : ctx.args[0].long_val;
+            if (permits < 0) {
+                std::cerr << "[JUC][LAW] Semaphore.<init>(" << permits
+                          << ") → IllegalArgumentException (JDK law)"
+                          << std::endl;
+                return juc_iae("initial permits < 0");
+            }
+            self->semaphore_permits_[recv] = permits;
+            std::cerr << "[JUC] Semaphore o" << recv << " ctor permits="
+                      << permits << std::endl;
+            return juc_void();
+        }
+        if (m == "availablePermits")
+            return juc_long(self->semaphore_permits(recv));
+        if (m == "drainPermits")
+            return juc_long(self->semaphore_drain(recv));
+        if (m == "tryAcquire") {
+            return juc_bool(self->semaphore_try_consume(recv, 1));
+        }
+        if (m == "release" || m == "releaseN") {
+            int64_t n = 1;
+            if (!ctx.args.empty()) {
+                n = ctx.args[0].kind == CallContext::Arg::Kind::LONG
+                        ? ctx.args[0].long_val
+                        : ctx.args[0].int_val;
+                if (n < 0)
+                    return juc_iae("release permits < 0");
+            }
+            self->semaphore_add(recv, n);
+            // JDK release law: wake ONE parked acquirer (it consumes the
+            // permit at its re-entry through the engine bridge).
+            if (auto* ts = reg ? reg->find_as<ThreadShadow>() : nullptr) {
+                size_t woken = ts->notify_monitor(recv, /*all=*/false);
+                std::cerr << "[JUC] Semaphore o" << recv << " release(" << n
+                          << ") → permits=" << self->semaphore_permits(recv)
+                          << " woke " << woken << " acquirer(s)" << std::endl;
+            }
+            return juc_void();
+        }
+        if (m == "acquire" || m == "acquireN" || m == "acquireUninterruptibly") {
+            int64_t n = 1;
+            if (!ctx.args.empty()) {
+                n = ctx.args[0].kind == CallContext::Arg::Kind::LONG
+                        ? ctx.args[0].long_val
+                        : ctx.args[0].int_val;
+                if (n < 0)
+                    return juc_iae("acquire permits < 0");
+            }
+            if (self->semaphore_try_consume(recv, n)) {
+                std::cerr << "[JUC] Semaphore o" << recv << " acquire(" << n
+                          << ") → permits=" << self->semaphore_permits(recv)
+                          << std::endl;
+                return juc_void();
+            }
+            std::cerr << "[JUC][BOUNDARY] Semaphore o" << recv
+                      << " acquire(" << n << ") insufficient ("
+                      << self->semaphore_permits(recv)
+                      << ") — park is engine-owned" << std::endl;
+            return juc_void();
+        }
+        return CallResult::not_handled();
+    }
+
+    // ── CyclicBarrier ────────────────────────────────────────────────
+    if (cls == "Ljava/util/concurrent/CyclicBarrier;") {
+        if (m == "<init>") {
+            int64_t parties = ctx.args.empty() ? 0 : ctx.args[0].long_val;
+            if (parties <= 0) {
+                std::cerr << "[JUC][LAW] CyclicBarrier.<init>(" << parties
+                          << ") → IllegalArgumentException (JDK law)"
+                          << std::endl;
+                return juc_iae("parties <= 0");
+            }
+            auto& st = self->barrier_states_[recv];
+            st.parties = parties;
+            st.waiting = 0;
+            st.broken = false;
+            std::cerr << "[JUC] CyclicBarrier o" << recv << " ctor parties="
+                      << parties << std::endl;
+            return juc_void();
+        }
+        if (m == "getParties")
+            return juc_long(self->barrier_parties(recv));
+        if (m == "getNumberWaiting")
+            return juc_long(self->barrier_number_waiting(recv));
+        if (m == "isBroken")
+            return juc_bool(self->barrier_is_broken(recv));
+        if (m == "reset") {
+            self->barrier_reset(recv);
+            std::cerr << "[JUC] CyclicBarrier o" << recv
+                      << " reset → fresh generation" << std::endl;
+            return juc_void();
+        }
+        if (m == "await" || m == "awaitJ") {
+            // The ENGINE bridge law parks non-tripping parties and trips
+            // the barrier from the LAST arrival. Shadow surface: answer
+            // the already-tripping case (this arrival completes the party
+            // count) so the shadow-only path stays honest.
+            auto& st = self->barrier_states_[recv];
+            if (st.waiting + 1 >= st.parties) {
+                self->barrier_trip(recv);
+                return juc_long(0);  // JDK: arrival index parties-1
+            }
+            self->barrier_register_waiter(recv);
+            std::cerr << "[JUC][BOUNDARY] CyclicBarrier o" << recv
+                      << " await — " << st.waiting << "/" << st.parties
+                      << " waiting; park is engine-owned" << std::endl;
