+    // ── Exchanger ────────────────────────────────────────────────────
+    if (cls == "Ljava/util/concurrent/Exchanger;") {
+        if (m == "<init>") return juc_void();
+        if (m == "exchange") {
+            uint32_t item = ctx.args.empty() ||
+                                    ctx.args[0].kind !=
+                                        CallContext::Arg::Kind::OBJECT
+                                ? 0
+                                : ctx.args[0].object_id;
+            if (self->exchanger_pending(recv)) {
+                // SECOND exchanger: pair completes NOW (JDK node pairing).
+                uint32_t theirs = self->exchanger_take_pending(recv);
+                uint32_t waiter = 0;
+                // wake the parked FIRST exchanger
+                if (auto* ts = reg ? reg->find_as<ThreadShadow>() : nullptr) {
+                    size_t woken = ts->notify_monitor(recv, /*all=*/true);
+                    (void)woken;
+                }
+                self->exchanger_set_resume_item(recv, item);
+                (void)waiter;
+                std::cerr << "[JUC] Exchanger o" << recv
+                          << " PAIRED — second exchanger returns o" << theirs
+                          << ", parked exchanger wakes with o" << item
+                          << std::endl;
+                if (theirs != 0)
+                    return CallResult::handled_object(
+                        theirs, "Ljava/lang/Object;");
+                return CallResult::handled_null();
