+            // SAME register_wait when it intercepts first in real app
+            // paths; the shadow surface mirrors it so the direct-dispatch
+            // path observes the identical WAITING state).
+            uint32_t self_oid = self_thread(self, reg);
+            if (self->exchanger_register(recv, self_oid, item)) {
+                if (auto* ts_e = reg ? reg->find_as<ThreadShadow>() : nullptr)
+                    ts_e->register_wait(self_oid, recv, INT64_MAX);
+                std::cerr << "[JUC][BOUNDARY] Exchanger o" << recv
+                          << " first exchange (item o" << item
+                          << ") — parked on the exchanger (WAITING)"
