+                              << cap << ") → IllegalArgumentException"
+                              << std::endl;
+                    return juc_iae("capacity <= 0");
+                }
+                if (is_lq && cap < 0) {
+                    self->queue_states_.erase(recv);
+                    return juc_iae("capacity < 0");
+                }
+                if (is_lq && cap == INT64_MAX) cap = 0x7fffffffLL;
+            }
+            q.capacity = cap;
+            std::cerr << "[JUC] " << (is_lq ? "Linked" : "Array")
+                      << "BlockingQueue o" << recv << " ctor capacity="
+                      << (cap == INT64_MAX ? std::string("unbounded")
+                                           : std::to_string(cap))
+                      << std::endl;
+            return juc_void();
+        }
+        if (m == "size" || m == "getCapacity")
+            return juc_long(static_cast<int64_t>(self->queue_size(recv)));
+        if (m == "isEmpty") return juc_bool(self->queue_size(recv) == 0);
+        if (m == "remainingCapacity") {
+            int64_t cap = self->queue_capacity(recv);
+            int64_t used = static_cast<int64_t>(self->queue_size(recv));
+            return juc_long(cap >= used ? cap - used : 0);
+        }
+        if (m == "put" || m == "offer" || m == "add") {
+            uint32_t el = ctx.args.empty() ? 0 : ctx.args[0].object_id;
+            std::string el_desc = "Ljava/lang/Object;";
+            if (!ctx.args.empty() && !ctx.args[0].object_class.empty())
+                el_desc = ctx.args[0].object_class;
