+                          << " put FULL (" << self->queue_size(recv)
+                          << "/" << cap << ") — park is engine-owned"
+                          << std::endl;
+                return juc_void();
+            }
+            if (full) return juc_bool(false);  // offer on full → false
+            self->queue_enqueue(recv, el, el_desc);
+            // S174-CONC (CODER 8, wave 5): the enqueue IS the notEmpty
+            // signal — a parked taker (registered on the queue oid by the
+            // engine law) wakes here (was: the S170 shadow put stored the
+            // element without the wake; the engine-side enqueue notifies
+            // but the direct-shadow surface did not — inconsistent roles).
+            if (auto* ts = reg ? reg->find_as<ThreadShadow>() : nullptr)
+                ts->notify_monitor(recv, /*all=*/false);
+            std::cerr << "[JUC] queue o" << recv << " put o" << el
+                      << " → size=" << self->queue_size(recv) << std::endl;
+            return (m == "offer") ? juc_bool(true)
+                                  : (m == "add" ? juc_bool(true) : juc_void());
+        }
+        if (m == "take" || m == "poll" || m == "remove") {
+            uint32_t el = 0;
+            std::string desc;
+            if (self->queue_take(recv, el, desc)) {
