+// TEST 37 — CyclicBarrier law (parties/waiting/trip/reset/broken/IAE).
+static void test37_barrier(DalvikHeap& heap, ThreadShadow* ts,
+                           HandlerShadow* hs, LocksShadow* ls) {
+    std::cout << "\n[TEST 37] CyclicBarrier law\n";
+    uint32_t bar = heap.allocate(kBar, 0, 0);
