+                          heap.allocate(kBar, 0, 0), {long_arg(0)});
+    check(neg.handled && neg.is_exc,
+          "ctor(0) → IllegalArgumentException (JDK parties<=0 law)");
+    call(ls, kBar, "<init>", true, bar, {long_arg(3)});
+    check(call(ls, kBar, "getParties", true, bar).long_val == 3,
+          "getParties == 3");
+    check(call(ls, kBar, "isBroken", true, bar).bool_val == false,
+          "fresh barrier is NOT broken");
+    // Two arrivals park (engine law registers via the same wait set).
+    uint32_t p1 = heap.allocate(kThread, 0, 0);
+    uint32_t p2 = heap.allocate(kThread, 0, 0);
+    ls->barrier_register_waiter(bar);
+    ls->barrier_register_waiter(bar);
+    ts->register_wait(p1, bar, INT64_MAX);
+    ts->register_wait(p2, bar, INT64_MAX);
+    ev(ts, hs, "TEST37 two parties waiting");
+    check(call(ls, kBar, "getNumberWaiting", true, bar).long_val == 2,
+          "getNumberWaiting == 2");
+    // The LAST arrival trips: release EVERY waiter + new generation.
+    ls->barrier_trip(bar);
+    bool intr37 = false, not37 = false;
+    check(ts->consume_wait_resume_result(p1, bar, &intr37, &not37) && not37,
+          "trip released party 1 (notified)");
+    check(ts->consume_wait_resume_result(p2, bar, &intr37, &not37) && not37,
+          "trip released party 2 (ALL parties — JDK barrierTripped law)");
+    check(call(ls, kBar, "getNumberWaiting", true, bar).long_val == 0,
+          "waiting reset to 0 after trip (new generation)");
+    // reset() mid-wait breaks the barrier for the waiters.
+    uint32_t p3 = heap.allocate(kThread, 0, 0);
+    ls->barrier_register_waiter(bar);
+    ts->register_wait(p3, bar, INT64_MAX);
+    call(ls, kBar, "reset", true, bar);
+    check(ts->consume_wait_resume_result(p3, bar, &intr37, &not37) && not37,
+          "reset released the waiter so it can surface the broken barrier");
+    check(call(ls, kBar, "isBroken", true, bar).bool_val == false,
+          "reset leaves a FRESH generation (not broken)");
+}
