+// TEST 39 — LinkedBlockingQueue element law (FIFO put/take/offer/poll/peek).
+static void test39_lbq(DalvikHeap& heap, ThreadShadow* ts, HandlerShadow* hs,
+                       LocksShadow* ls) {
+    std::cout << "\n[TEST 39] LinkedBlockingQueue element law\n";
+    uint32_t q = heap.allocate(kLBQ, 0, 0);
+    call(ls, kLBQ, "<init>", true, q);
+    uint32_t e1 = heap.allocate(kTaskCls, 0, 0);
+    uint32_t e2 = heap.allocate(kTaskCls, 0, 0);
+    check(call(ls, kLBQ, "put", true, q, {obj_arg(e1)}).handled,
+          "put(e1) accepted");
+    check(call(ls, kLBQ, "put", true, q, {obj_arg(e2)}).handled,
+          "put(e2) accepted");
+    check(call(ls, kLBQ, "size", true, q).long_val == 2, "size == 2");
+    CallResult peek = call(ls, kLBQ, "peek", true, q);
+    check(peek.handled && peek.object_id == e1,
+          "peek returns the HEAD without removal (FIFO)");
+    check(call(ls, kLBQ, "size", true, q).long_val == 2, "size still 2");
+    CallResult t1 = call(ls, kLBQ, "take", true, q);
+    check(t1.handled && t1.object_id == e1, "take → e1 FIRST (FIFO law)");
+    CallResult t2 = call(ls, kLBQ, "poll", true, q);
+    check(t2.handled && t2.object_id == e2, "poll → e2");
+    CallResult t3 = call(ls, kLBQ, "poll", true, q);
+    check(t3.handled && t3.ret_kind == CallResult::RetKind::NULL_REF,
+          "poll on EMPTY → null (non-blocking contract)");
+    CallResult rem = call(ls, kLBQ, "remainingCapacity", true, q);
+    check(rem.handled && rem.long_val > 1000000000LL,
+          "unbounded LinkedBlockingQueue → huge remainingCapacity");
+    CallResult np = call(ls, kLBQ, "put", true, q, {null_arg()});
+    check(np.handled && np.is_exc, "put(null) → NPE (JDK law)");
+    ev(ts, hs, "TEST39 lbq FIFO walk");
+}
