+// TEST 125 — MessageQueue.isIdle AOSP law (FIX 13).
+static void test125_mq_is_idle(DalvikHeap& heap, ThreadShadow* ts,
+                               HandlerShadow* hs, LooperShadow* lop) {
+    std::cout << "\n[TEST 125] MessageQueue.isIdle\n";
+    uint32_t mq = heap.allocate(kMQ, 0, 0);
