+    uint32_t r = heap.allocate(kTaskCls, 0, 0);
+    hs->enqueue_tokened(r, 1000, kTaskCls, 0);
+    // AOSP isIdle(): mMessages == null || now < mMessages.when — a
+    // FUTURE-due first message leaves the looper with nothing to process
+    // NOW → isIdle TRUE (the AOSP semantics; the pre-wave-7 shape was
+    // unimplemented).
+    check(call(lop, kMQ, "isIdle", true, mq).bool_val,
+          "a future-due message → isIdle TRUE (now < mMessages.when)");
+    hs->advance_virtual(1000);
+    // At now == when the message is DUE (not yet drained): isIdle false —
+    // the looper has work at this instant (AOSP now < when fails).
+    check(!call(lop, kMQ, "isIdle", true, mq).bool_val,
+          "a due (not-yet-drained) message → isIdle false");
+    std::vector<uint32_t> drained7;
+    hs->drain_ready(&drained7);
+    check(call(lop, kMQ, "isIdle", true, mq).bool_val,
+          "after the due message drains → isIdle true again");
+    ev(ts, hs, "TEST125 mq isIdle");
+}
