+package com.probe.c7runtime;
+
+/** CODER7 probe: shared delivery-order recorder. */
+public class Order {
+    public static final StringBuilder seq = new StringBuilder();
+    public static void append(String who) {
+        if (seq.length() > 0) seq.append(",");
+        seq.append(who);
+    }
+    public static void reset() { seq.setLength(0); }
+}
