+static std::vector<uint8_t> build_type_spec(uint8_t type_id, uint32_t flags) {
+    std::vector<uint8_t> out;
+    append16(out, 0x0202); append16(out, 16); append32(out, 16 + 4);
+    out.push_back(type_id); out.push_back(0); append16(out, 0);
+    append32(out, 1);
+    append32(out, flags);
+    return out;
