diff --git a/miniandroid/tests/s180_coderd_confirmed_law_test.cpp b/miniandroid/tests/s180_coderd_confirmed_law_test.cpp
new file mode 100644
index 00000000..10d4ff77
--- /dev/null
+++ b/miniandroid/tests/s180_coderd_confirmed_law_test.cpp
@@ -0,0 +1,263 @@
+/*
+ * S180 (CODER 3) — Coder-D confirmed-findings law test, unit tier.
+ *
+ * Pins the directly-testable subset of the S178 verdict's CONFIRMED list
+ * (manager verdict issuecomment on #529, base 09e952af/S177; fixes applied
+ * at base e0bbffaa/S179):
+ *
+ *   P2-2  parse_array_index strict numeric body ("array[]"/"array[abc]"
+ *         must NOT alias index 0)                       [dalvik_engine.h]
+ *   P2-1  HeapObject array_store bounded growth         [dalvik_engine.h]
+ *   P2-16 encoded_value nested ARRAY/ANNOTATION depth cap [encoded_value.h]
+ *   P1-7  prefs parseXml malformed numerics degrade to
+ *         string instead of throwing out of loadFromFile [shared_prefs.cpp]
+ *   P3-6  prefs parseXml empty element no longer UB      [shared_prefs.cpp]
+ *   P2-7  apply() is a synchronous memory commit: readers observe the new
+ *         values immediately and listeners fire          [shared_prefs.cpp]
+ *   P2-10 unregister removes only the matching listener  [shared_prefs.cpp]
+ *   P2-11 notifyListeners({}) is a safe no-op            [shared_prefs.cpp]
+ *   P3-13 write_reports fails loudly on an unwritable dir [trace_engine.cpp]
+ *
+ * The engine-level laws (P0-4 guard, P0-5 0x06 case + 32x direction,
+ * P2-5 tries sentinel, P2-6 sign-extension, P0-6 alloc cap, P2-14 dtor,
+ * P3-1/P3-12) are exercised by the corpus A/B battery and per-law source
+ * review; this file pins the pure/kernel-adjacent subset.
+ *
+ * Build: see scripts/s180_build_law_test.sh. Expect 24/24.
+ */
+
+#include "dalvik_engine.h"
+#include "encoded_value.h"
+#include "shared_prefs.h"
+#include "trace_engine.h"
+
+#include <cstdio>
+#include <fstream>
+#include <sys/stat.h>
+
+using namespace miniandroid;
+using namespace miniandroid::dex;
+using namespace miniandroid::dalvik;
+using namespace miniandroid::diagnostics;
+using namespace AndroidAPI;
+
+static int g_pass = 0, g_fail = 0;
+#define LAW(cond, num, name)                                                   \
+    do {                                                                       \
+        if (cond) { ++g_pass; }                                                \
+        else { ++g_fail;                                                       \
+            std::printf("  LAW %02d FAIL: %s\n", (num), (name)); }             \
+    } while (0)
+
+// ---------------------------------------------------------------------------
+// P2-10/P2-7 listener plumbing — plain function pointers so the unregister
+// identity law (function-pointer target match) is exercised exactly.
+// ---------------------------------------------------------------------------
+static int g_l1_hits = 0, g_l2_hits = 0, g_apply_hits = 0;
+static std::string g_last_key;
+static void listener_1(SharedPreferences*, const std::string& k) { ++g_l1_hits; g_last_key = k; }
+static void listener_2(SharedPreferences*, const std::string& k) { ++g_l2_hits; g_last_key = k; }
+static void listener_apply(SharedPreferences*, const std::string&) { ++g_apply_hits; }
+
+static std::string write_temp_xml(const char* name, const std::string& body) {
+    std::string path = std::string("/tmp/s180_lawtest_") + name + ".xml";
+    std::ofstream f(path);
+    f << "<?xml version='1.0' encoding='utf-8' standalone='yes' ?>\n"
+      << "<map>\n" << body << "</map>\n";
+    f.close();
+    return path;
+}
+
+int main() {
+    std::printf("== S180 Coder-D confirmed-findings law test ==\n");
+
+    // ------------------------------------------------------------------
+    // P2-2 — parse_array_index strict numeric body
+    // ------------------------------------------------------------------
+    {
+        HeapObject o;
+        int32_t v = -1;
+        LAW(HeapObject::parse_array_index("array[5]", v) && v == 5, 1,
+            "array[5] parses to 5");
+        LAW(!HeapObject::parse_array_index("array[]", v), 2,
+            "array[] rejected (was index 0)");
+        LAW(!HeapObject::parse_array_index("array[abc]", v), 3,
+            "array[abc] rejected (was index 0)");
+        LAW(!HeapObject::parse_array_index("array[1x]", v), 4,
+            "array[1x] rejected");
+        LAW(!HeapObject::parse_array_index("array[99999999999]", v), 5,
+            "overflowing body rejected");
+        LAW(HeapObject::parse_array_index("array[2147483647]", v) &&
+            v == 2147483647, 6, "int32-max body accepted");
+    }
+
+    // ------------------------------------------------------------------
+    // P2-1 — array_store bounded growth + normal store/load roundtrip
+    // ------------------------------------------------------------------
+    {
+        HeapObject o;
+        o.set_field("array[3]", DalvikValue::make_int(42));
+        DalvikValue got = o.get_field("array[3]");
+        LAW(got.type == DalvikType::INT32 && got.int_val == 42, 7,
+            "normal shadow array store/load roundtrip");
+        o.set_field("array[2000000000]", DalvikValue::make_int(7));
+        LAW(o.array_store.size() < (1u << 20), 8,
+            "hostile index does not resize array_store to 2e9");
+        LAW(o.get_field("array[2000000000]").type == DalvikType::UNINITIALIZED, 9,
+            "hostile index reads back uninit (symmetric drop)");
+    }
+
+    // ------------------------------------------------------------------
+    // P2-16 — encoded_value depth cap
+    // ------------------------------------------------------------------
+    {
+        // Nesting bomb: N nested VALUE_ARRAY (0x1c) wrappers, each with
+        // uleb count 0x01, innermost a VALUE_BOOLEAN (0x1f, no payload).
+        auto build_nested = [](size_t depth) {
+            std::string s;
+            for (size_t i = 0; i < depth; ++i) s += "\x1c\x01";
+            s += "\x1f";
+            return s;
+        };
+        {
+            std::string ok = build_nested(3);
+            size_t p = 0; EncodedValue out;
+            LAW(read_encoded_value(
+                    reinterpret_cast<const uint8_t*>(ok.data()), ok.size(), p,
+                    out), 10, "3-deep nested array decodes (no false cap)");
+        }
+        {
+            std::string bomb = build_nested(100);
+            size_t p = 0; EncodedValue out;
+            LAW(!read_encoded_value(
+                    reinterpret_cast<const uint8_t*>(bomb.data()), bomb.size(),
+                    p, out), 11, "100-deep nested array rejected (depth cap)");
+        }
+    }
+
+    // ------------------------------------------------------------------
+    // P1-7 + P3-6 — malformed prefs XML degrades, never throws
+    // ------------------------------------------------------------------
+    {
+        std::string path = write_temp_xml(
+            "malformed",
+            "<int name=\"bad\" value=\"abc\"/>\n"
+            "<long name=\"badl\" value=\"xyz\"/>\n"
+            "<float name=\"badf\" value=\"1.2.3\"/>\n"
+            "<int name=\"ok\" value=\"42\"/>\n"
+            "<>\n");  // P3-6: empty element — old code did element.back() UB
+        SharedPreferences prefs{fs::path(path)};
+        bool no_throw = true;
+        try {
+            // The path-ctor auto-loads (shared_prefs.cpp:225); on the OLD
+            // code the std::stoi throw would fire inside this construction.
+            (void)prefs.getInt("ok", -7);
+        } catch (...) {
+            no_throw = false;
+        }
+        LAW(no_throw, 12, "malformed XML loads without throwing");
+        LAW(prefs.getString("bad", "MISS") == "abc", 13,
+            "malformed <int> kept as string value");
+        LAW(prefs.getInt("ok", -7) == 42, 14,
+            "valid <int> still parses to 42 (no regression)");
+    }
+
+    // ------------------------------------------------------------------
+    // P2-7 — apply(): synchronous visibility + listener notification
+    // ------------------------------------------------------------------
+    {
+        std::string path = write_temp_xml("apply", "");
+        SharedPreferences prefs{fs::path(path)};
+        prefs.edit().putString("k", "v").apply();
+        LAW(prefs.getString("k", "MISS") == "v", 15,
+            "apply() is synchronously visible to readers");
+        g_apply_hits = 0;
+        prefs.registerOnSharedPreferenceChangeListener(listener_apply);
+        prefs.edit().putString("k2", "v2").apply();
+        prefs.unregisterOnSharedPreferenceChangeListener(listener_apply);
+        LAW(g_apply_hits >= 1, 16, "apply() notifies listeners (AOSP law)");
+        prefs.edit().putString("k3", "v3").apply();
+        LAW(g_apply_hits == 1, 17,
+            "unregistered apply-listener no longer fires (P2-10 synergy)");
+    }
+
+    // ------------------------------------------------------------------
+    // P2-10 — unregister removes ONLY the matching listener
+    // ------------------------------------------------------------------
+    {
+        std::string path = write_temp_xml("unreg", "");
+        SharedPreferences prefs{fs::path(path)};
+        g_l1_hits = 0; g_l2_hits = 0;
+        prefs.registerOnSharedPreferenceChangeListener(listener_1);
+        prefs.registerOnSharedPreferenceChangeListener(listener_2);
+        prefs.unregisterOnSharedPreferenceChangeListener(listener_1);
+        prefs.edit().putString("u", "1").commit();
+        LAW(g_l1_hits == 0, 18, "unregistered listener stays silent");
+        LAW(g_l2_hits >= 1, 19,
+            "other listener survives unregister (was mass-cleared)");
+        LAW(g_last_key == "u", 20, "listener receives the changed key");
+    }
+
+    // ------------------------------------------------------------------
+    // P2-11 — notifyListeners({}) is a safe no-op (via the public commit
+    // path: an empty editor commit produces an empty changed-key set)
+    // ------------------------------------------------------------------
+    {
+        std::string path = write_temp_xml("emptykeys", "");
+        SharedPreferences prefs{fs::path(path)};
+        prefs.registerOnSharedPreferenceChangeListener(listener_1);
+        g_l1_hits = 0;
+        bool crashed = false;
+        try {
+            prefs.edit().commit();  // nothing modified -> notifyListeners({})
+        } catch (...) {
+            crashed = true;
+        }
+        LAW(!crashed && g_l1_hits == 0, 21,
+            "empty changed-key set is a safe no-op (was *keys.begin() UB)");
+        prefs.unregisterOnSharedPreferenceChangeListener(listener_1);
+    }
+
+    // ------------------------------------------------------------------
+    // P3-13 — write_reports fails loudly on an unwritable directory
+    // ------------------------------------------------------------------
+    {
+        const char* dir = "/tmp/s180_lawtest_unwritable";
+        ::mkdir(dir, 0755);
+        ::chmod(dir, 0555);  // r-x: create-file inside must fail for non-root
+        TraceEngine te;
+        bool ok = te.write_reports(dir, "app", "SUCCESS", "/tmp/x.apk");
+        ::chmod(dir, 0755);
+        LAW(!ok, 22, "write_reports returns false when files cannot open");
+    }
+
+    // ------------------------------------------------------------------
+    // P2-10 regression — unregister of an unregistered callable is inert
+    // (no mass-clear side effect)
+    // ------------------------------------------------------------------
+    {
+        std::string path = write_temp_xml("unreg2", "");
+        SharedPreferences prefs{fs::path(path)};
+        g_l2_hits = 0;
+        prefs.registerOnSharedPreferenceChangeListener(listener_2);
+        prefs.unregisterOnSharedPreferenceChangeListener(listener_1);  // never registered
+        prefs.edit().putString("w", "1").commit();
+        LAW(g_l2_hits >= 1, 23,
+            "unregistering a stranger does not detach other listeners");
+        prefs.unregisterOnSharedPreferenceChangeListener(listener_2);
+    }
+
+    // ------------------------------------------------------------------
+    // P2-2 synergy — strict parse means non-array names reach fields map
+    // ------------------------------------------------------------------
+    {
+        HeapObject o;
+        o.set_field("array[]", DalvikValue::make_int(9));
+        DalvikValue got = o.get_field("array[]");
+        LAW(got.type == DalvikType::INT32 && got.int_val == 9, 24,
+            "rejected index form falls back to the fields map");
+    }
+
+    std::printf("== %d/%d passed ==\n", g_pass, g_pass + g_fail);
+    return g_fail == 0 ? 0 : 1;
+}
