+#!/usr/bin/env bash
+# s180 — build + run the Coder-D confirmed-findings law test.
+# Links the FULL engine object set minus main.o plus the test object
+# (same pattern as the C9 law tests, Issue #521 ACH-1 §7).
+set -e
+cd "$(dirname "$0")/../miniandroid"
+
+TEST=tests/s180_coderd_confirmed_law_test.cpp
+OUT=build/s180_law_test
+
+OBJS=$(find build -name '*.o' ! -name 'main.o' | sort | tr '\n' ' ')
+
+g++ -std=c++17 -Wall -Wextra -g -O2 -MMD -MP -DMINIANDROID_HAVE_WEBP \
+    -Isrc -Isrc/webview -Isrc/apk -Isrc/dex -Isrc/runtime -Isrc/api \
+    -Isrc/graphics -Isrc/diagnostics -Isrc/resources -Isrc/renderer \
+    -Isrc/framework -Isrc/storage -Isrc/fonts -Ithird_party/portablegl \
+    -I/usr/include/freetype2 -Ithird_party/nlohmann_json/include \
+    -o "$OUT" "$TEST" $OBJS \
+    -lz -ljpeg -lstdc++ -lm -lpthread -lsqlite3 -lssl -lcrypto -lmpg123 \
+    -lsndfile -lwebp -lwebpdemux -lfreetype -lharfbuzz -lfribidi -lpng
+
+echo "build ok: $OUT"
+"$OUT"
-- 
2.47.3


