+// libgdx-freetype}.so, x86_64) emits `.init_array` with exactly one entry
+// whose file value is 0x0 with NO relocation targeting it. bionic's
+// soinfo::call_function skips null ctor entries — every real Android
+// device runs these libraries; glibc's call_init calls EVERY entry
+// unconditionally → dlopen jumps to address 0 → SIGSEGV si_addr=0x0 (the
+// S183 B1 frontier, fork-probe FAULTED verdict).
+//
+// Law: in the RUNTIME-OWNED EXTRACTED COPY (never the APK — same scope as
+// the F-NEW-461 version-tag rewrite), when at least one init_array entry
+// is genuinely null:
+//   1. zero DT_INIT_ARRAYSZ (value-only edit; the dynamic table stays
+//      contiguous and every other entry untouched — the loader loop then
+//      runs zero ctors),
+//   2. neutralize DT_INIT/DT_FINI when their value is 0 (tag → ignorable
+//      high tag 0x7ffffffe; calling base+0 would execute the ELF header),
+//   3. hand the non-null ctors back to the caller as vaddrs — they run
+//      AFTER dlopen under the FIX-TTT fault guard (bionic parity: nulls
+//      skipped, reals executed, faults bounded),
+//   4. same null-skip for fini_array (dlclose would otherwise die in the
+//      loader's fini loop).
+// IRELATIVE relocations on init entries abort the surgery honestly (their
+// resolved addresses cannot be computed statically; the loader must own
+// them). Byte-inertness: libraries with NO null entries (bouncy box2d,
+// tower3d gdx — zero init_array entries) take NO surgery at all.
+bool bionic_init_null_fixup(const std::string& path, BionicInitFixup& out,
+                            std::string& why) {
+    out = BionicInitFixup{};
+    std::vector<uint8_t> buf;
+    if (!read_file(path, buf) || buf.size() < sizeof(Elf64Ehdr)) {
+        why = "unreadable";
+        return false;
+    }
+    Elf64Ehdr e;
+    std::memcpy(&e, buf.data(), sizeof e);
+    if (e.e_phentsize < sizeof(Elf64Phdr) || e.e_phoff == 0 ||
+        e.e_phoff + (uint64_t)e.e_phnum * e.e_phentsize > buf.size()) {
+        why = "no program headers";
+        return false;
+    }
+    // PT_LOAD vaddr→file mapping + PT_DYNAMIC.
+    struct Load { uint64_t vaddr, filesz, offset; };
+    std::vector<Load> loads;
+    const Elf64Dyn* dyn = nullptr;
+    size_t dyn_n = 0;
+    for (uint32_t i = 0; i < e.e_phnum; ++i) {
+        Elf64Phdr p;
+        std::memcpy(&p, buf.data() + e.e_phoff + (size_t)i * e.e_phentsize,
+                    sizeof p);
+        if (p.p_type == PT_LOAD)
+            loads.push_back({p.p_vaddr, p.p_filesz, p.p_offset});
+        if (p.p_type == PT_DYNAMIC) {
+            if (p.p_offset + p.p_filesz > buf.size()) {
+                why = "bad PT_DYNAMIC";
+                return false;
+            }
+            dyn = reinterpret_cast<const Elf64Dyn*>(buf.data() + p.p_offset);
+            dyn_n = p.p_filesz / sizeof(Elf64Dyn);
+        }
+    }
+    if (!dyn) { why = "no PT_DYNAMIC"; return false; }
+    auto v2f = [&](uint64_t v) -> int64_t {
+        for (const auto& L : loads)
+            if (L.vaddr <= v && v < L.vaddr + L.filesz)
+                return (int64_t)(L.offset + (v - L.vaddr));
+        return -1;
+    };
+    constexpr int64_t DT_INIT = 12, DT_FINI = 13;
+    constexpr uint64_t DT_INIT_ARRAY = 25, DT_INIT_ARRAYSZ = 27;
+    constexpr uint64_t DT_FINI_ARRAY = 26, DT_FINI_ARRAYSZ = 28;
+    int64_t init_arr_off = -1, fini_arr_off = -1;
+    size_t init_n = 0, fini_n = 0;
+    int64_t init_arrsz_dyn = -1, fini_arrsz_dyn = -1;
+    int64_t init_tag_dyn = -1, fini_tag_dyn = -1;
+    int64_t init_tag_dyn2 = -1;  // DT_INIT_ARRAY tag entry (rev2 surgery)
+    int64_t fini_tag_dyn2 = -1;  // DT_FINI_ARRAY tag entry (rev2 surgery)
+    uint64_t dt_init_val = 0, dt_fini_val = 0;
+    uint64_t dt_initarr_vaddr = 0, dt_finiarr_vaddr = 0;
+    for (size_t i = 0; i < dyn_n && dyn[i].d_tag != DT_NULL; ++i) {
+        const int64_t tag = dyn[i].d_tag;
+        const uint64_t val = dyn[i].d_val;
+        const int64_t entry_off =
+            (int64_t)((const uint8_t*)&dyn[i] - buf.data());
+        switch (tag) {
+            case DT_INIT: dt_init_val = val; init_tag_dyn = entry_off; break;
+            case DT_FINI: dt_fini_val = val; fini_tag_dyn = entry_off; break;
+            case DT_INIT_ARRAY: {
+                dt_initarr_vaddr = val;
+                init_tag_dyn2 = entry_off;
+                const int64_t fo = v2f(val);
+                if (fo >= 0) init_arr_off = fo;
+                break;
+            }
+            case DT_INIT_ARRAYSZ: init_n = (size_t)val; init_arrsz_dyn = entry_off; break;
+            case DT_FINI_ARRAY: {
+                dt_finiarr_vaddr = val;
+                fini_tag_dyn2 = entry_off;
+                const int64_t fo = v2f(val);
+                if (fo >= 0) fini_arr_off = fo;
+                break;
+            }
+            case DT_FINI_ARRAYSZ: fini_n = (size_t)val; fini_arrsz_dyn = entry_off; break;
+            default: break;
+        }
+    }
+    out.inspected = true;
+    if (init_arr_off < 0 && fini_arr_off < 0 && init_tag_dyn < 0 &&
+        fini_tag_dyn < 0) {
+        out.note = "no init/fini arrays; nothing to do";
+        return true;
+    }
+    // DT_*_ARRAYSZ counts BYTES; entries are pointer-sized (8 on x86-64).
+    init_n = init_arr_off >= 0 ? init_n / 8 : 0;
+    fini_n = fini_arr_off >= 0 ? fini_n / 8 : 0;
+    // Relocation scan for the array slots (.rela.dyn via section headers).
+    constexpr uint32_t SHT_RELA = 4;
+    constexpr uint32_t R_X86_64_RELATIVE = 8, R_X86_64_IRELATIVE = 37;
+    std::vector<std::pair<uint64_t, uint64_t>> relative_at;  // vaddr→addend
+    bool irelative = false;
+    if (e.e_shoff && e.e_shentsize >= sizeof(Elf64Shdr) &&
+        e.e_shoff + (uint64_t)e.e_shnum * e.e_shentsize <= buf.size()) {
+        for (uint16_t i = 0; i < e.e_shnum; ++i) {
+            Elf64Shdr s;
+            std::memcpy(&s, buf.data() + e.e_shoff + (size_t)i * e.e_shentsize,
+                        sizeof s);
+            if (s.sh_type != SHT_RELA) continue;
+            if (s.sh_offset + s.sh_size > buf.size()) continue;
+            const size_t n = (size_t)(s.sh_size / sizeof(Elf64Rela));
+            for (size_t k = 0; k < n; ++k) {
+                Elf64Rela r;
+                std::memcpy(&r, buf.data() + s.sh_offset + k * sizeof r,
+                            sizeof r);
+                const uint32_t type = (uint32_t)(r.r_info & 0xffffffffu);
+                if (type == R_X86_64_RELATIVE)
+                    relative_at.emplace_back(r.r_offset, r.r_addend);
+                else if (type == R_X86_64_IRELATIVE)
+                    irelative = true;
+            }
+        }
+    }
+    auto effective = [&](uint64_t slot_vaddr, uint64_t file_val,
+                         bool& real) -> uint64_t {
+        real = false;
+        for (const auto& rv : relative_at)
+            if (rv.first == slot_vaddr) { real = true; return rv.second; }
+        if (file_val != 0) real = true;
+        return file_val;  // 0 and unreloc'd = genuinely null (bionic skips)
+    };
+    bool changed = false;
+    // init_array null-skip.
+    if (init_arr_off >= 0 && init_n > 0) {
+        if (irelative) {
+            out.irelative_seen = true;
+            out.note = "IRELATIVE on init: surgery aborted (loader owns it)";
+            why = out.note;
+            return true;
+        }
+        out.entries = init_n;
+        for (size_t i = 0; i < init_n; ++i) {
+            const uint64_t slot = (uint64_t)dt_initarr_vaddr + i * 8;
+            bool real = false;
+            uint64_t file_val = 0;
+            std::memcpy(&file_val, buf.data() + init_arr_off + i * 8, 8);
+            const uint64_t eff = effective(slot, file_val, real);
+            if (real)
+                out.real_ctors.push_back(eff);
+            else
+                ++out.null_entries;
+        }
+        if (out.null_entries > 0 && init_arrsz_dyn >= 0 && init_tag_dyn2 >= 0) {
+            // Tag-removal surgery (F-NEW-572 rev2): exchange the
+            // DT_INIT_ARRAY TAG for an ignorable high tag so the loaded
+            // link_map shape matches a library with NO init_array at all
+            // (the tower3d libgdx.so shape, empirically clean at exit).
+            // Zeroing DT_INIT_ARRAYSZ alone (rev1) left the tag present
+            // and crashed glibc's exit-time fini walk (rip ld-linux
+            // +0x1fa2, fault_addr=0x8, chain exit→atexit→_dl_fini).
+            const int64_t ign = 0x7ffffffe;
+            std::memcpy(buf.data() + init_tag_dyn2, &ign, 8);
+            out.neutralized = true;
+            changed = true;
+        }
+    }
+    // fini_array null-skip (dlclose dies in the loader's fini loop).
+    if (fini_arr_off >= 0 && fini_n > 0 && !irelative) {
+        for (size_t i = 0; i < fini_n; ++i) {
+            uint64_t file_val = 0;
+            std::memcpy(&file_val, buf.data() + fini_arr_off + i * 8, 8);
+            bool real = false;
+            effective((uint64_t)dt_finiarr_vaddr + i * 8, file_val, real);
+            if (!real) ++out.fini_neutralized;
+        }
+        if (out.fini_neutralized > 0 && fini_arrsz_dyn >= 0 && fini_tag_dyn2 >= 0) {
+            const int64_t ign = 0x7ffffffe;
+            std::memcpy(buf.data() + fini_tag_dyn2, &ign, 8);
+            changed = true;
+        }
+    }
+    // DT_INIT/DT_FINI pointing at 0: glibc would call base+0 (the ELF
+    // header); bionic skips. Neutralize the tag.
+    constexpr int64_t DT_IGNORE_TAG = 0x7ffffffe;  // unknown → glibc ignores
+    if (init_tag_dyn >= 0 && dt_init_val == 0) {
+        std::memcpy(buf.data() + init_tag_dyn, &DT_IGNORE_TAG, 8);
+        changed = true;
+    }
+    if (fini_tag_dyn >= 0 && dt_fini_val == 0) {
+        std::memcpy(buf.data() + fini_tag_dyn, &DT_IGNORE_TAG, 8);
+        changed = true;
+    }
+    if (changed) {
+        std::ofstream f(path, std::ios::binary | std::ios::trunc);
+        if (!f) { why = "write failed"; return false; }
+        f.write(reinterpret_cast<const char*>(buf.data()),
+                (std::streamsize)buf.size());
+        if (!f) { why = "write failed"; return false; }
+    }
+    {
+        char b[256];
+        snprintf(b, sizeof b,
+                 "init_array entries=%zu nulls=%zu reals=%zu surgery=%s "
+                 "fini_nulls=%zu%s",
+                 out.entries, out.null_entries, out.real_ctors.size(),
+                 out.neutralized ? "DT_INIT_ARRAYSZ->0" : "none",
+                 out.fini_neutralized, irelative ? " IRELATIVE-seen" : "");
+        out.note = b;
+    }
+    return true;
+}
