+#!/usr/bin/env python3
+"""s191_gmdice_decode.py — androground-driven decode of de.duenndns.gmdice_8.
+
+The S157 wave (#560) left gmdice as the third-smallest canonical app
+(23 classes, 124 framework refs) with its ListView row-tap semantics
+(ListActivity) undriven. This script rebuilds the S157 toolchain
+(lost to sandbox recycle) and produces the static ground truth needed
+to drive gmdice to complete execution:
+
+  1. full class inventory (extends/implements, method count)
+  2. framework API refs grouped by root package
+  3. the app's own method disassembly for ListActivity lifecycle +
+     row-click semantics (onListItemClick / ListView.OnItemClickListener)
+  4. const strings (dice presets / format strings)
+  5. AndroidManifest: launcher activity, minSdk
+  6. res/layout AXML decode (ListView + row layout ids)
+
+Output: evidence/s191_gmdice/S191_GMDICE_DECODE.json (durable, in-repo).
+"""
+import json
+import re
+import sys
+from pathlib import Path
+
+from loguru import logger
+logger.remove()  # silence androguard DEBUG spam
+from androguard.core.apk import APK
+from androguard.core.dex import DEX
+from androguard.misc import AnalyzeDex
+
+BASE = Path("/home/z/my-project")
+APK_PATH = BASE / "upload/canonical_apks_restored/de.duenndns.gmdice_8.apk"
+OUT = Path("/home/z/my-project/work/repo/evidence/s191_gmdice")
+OUT.mkdir(parents=True, exist_ok=True)
+
+a = APK(str(APK_PATH))
+pkg = a.get_package()
+main_act = a.get_main_activity()
+min_sdk = a.get_min_sdk_version()
+tgt_sdk = a.get_target_sdk_version()
+
+# ---- 1. dex load ----
+dex_bytes = a.get_dex()
+d = DEX(dex_bytes)
+
+classes = {}
+for c in d.get_classes():
+    name = c.get_name()
+    entry = {
+        "super": c.get_superclassname(),
+        "access": c.get_access_flags_string(),
+        "interfaces": list(c.get_interfaces()),
+        "methods": [],
+        "fields": [],
+    }
+    for m in c.get_methods():
+        entry["methods"].append({
+            "n": m.get_name(),
+            "d": m.get_descriptor(),
+            "acc": m.get_access_flags_string(),
+            "code_units": (m.get_code().get_length() if m.get_code() else 0),
+        })
+    for f in c.get_fields():
+        entry["fields"].append({
+            "n": f.get_name(), "t": f.get_descriptor(),
+            "acc": f.get_access_flags_string(),
+        })
+    classes[name] = entry
+
+# ---- 2. framework refs (walk class-defined methods only) ----
+FRAME_PKGS = ("android/", "java/", "javax/", "org/apache/", "org/json/")
+fw_refs = {}
+own_refs = set()
+all_methods = []
+for c in d.get_classes():
+    for m in c.get_methods():
+        all_methods.append(m)
+        code = m.get_code()
+        if not code:
+            continue
+        for ins in m.get_instructions():
+            op = ins.get_name()
+            if op.startswith(("invoke-", "invoke/")):
+                try:
+                    operand = ins.get_translated_kind() or ins.get_kind()
+                except Exception:
+                    operand = ""
+                mm = re.search(r"L([^;]+);->(\S+)", str(operand))
+                if not mm:
+                    continue
+                cls, meth = mm.group(1), mm.group(2)
+                if cls.startswith(FRAME_PKGS):
+                    fw_refs.setdefault(f"{cls}->{meth}", 0)
+                    fw_refs[f"{cls}->{meth}"] += 1
+                else:
+                    own_refs.add(f"{cls}->{meth}")
+
+# ---- 3. strings ----
+strings = [s for s in d.get_strings()]
+interesting = [s for s in strings if 2 < len(s) < 120 and not s.startswith("L")]
+
+# ---- 4. disassemble key app methods (lifecycle + click + adapter) ----
+def disasm(class_hint, name_hint=None, max_ins=400):
+    rows = []
+    for c in d.get_classes():
+        for m in c.get_methods():
+            cn = m.get_class_name()
+            if class_hint not in cn:
+                continue
+            if name_hint and name_hint not in m.get_name():
+                continue
+            code = m.get_code()
+            if not code:
+                continue
+            rows.append({
+                "method": f"{cn}->{m.get_name()}{m.get_descriptor()}",
+                "ins": [(i.get_name(), (i.get_output() or "").strip()[:110])
+                        for i in list(m.get_instructions())[:max_ins]],
+            })
+    return rows
+
+key_disasm = {}
+key_disasm["main_activity"] = disasm("gmdice", "onCreate")
+key_disasm["list_click"] = disasm("gmdice", "onListItemClick") + disasm("gmdice", "onListItem")
+key_disasm["click_family"] = disasm("gmdice", "onClick")
+key_disasm["resume"] = disasm("gmdice", "onResume")
+key_disasm["adapter"] = disasm("gmdice", "getView")
+
+out = {
+    "apk": str(APK_PATH),
+    "package": pkg,
+    "main_activity": main_act,
+    "min_sdk": min_sdk,
+    "target_sdk": tgt_sdk,
+    "n_classes": len(classes),
+    "classes": classes,
+    "n_fw_refs": len(fw_refs),
+    "fw_refs_top": sorted(fw_refs.items(), key=lambda kv: -kv[1])[:120],
+    "own_refs": sorted(own_refs),
+    "strings": sorted(interesting)[:300],
+    "key_disasm": key_disasm,
+}
+dest = OUT / "S191_GMDICE_DECODE.json"
+dest.write_text(json.dumps(out, indent=1))
+print("WROTE", dest, dest.stat().st_size, "bytes")
+print("package", pkg, "main", main_act, "minSdk", min_sdk, "tgt", tgt_sdk)
+print("classes", len(classes), "fw_refs", len(fw_refs))
+for cl in sorted(classes):
+    print("  ", cl, "<-", classes[cl]["super"], "methods:", len(classes[cl]["methods"]))
+
+# ---- S191 extension: dump the FULL gameplay chain disassembly ----
