+fam2["gm_onClick"] = disasm("GameMasterDice", "onClick")
+fam2["gm_roll"] = disasm("GameMasterDice", "roll")
+fam2["gm_loadPrefs"] = disasm("GameMasterDice", "loadDicePrefs")
+fam2["gm_configureDice"] = disasm("GameMasterDice", "configureDice")
+fam2["gm_selectDice"] = disasm("GameMasterDice", "selectDice")
+fam2["gm_onResume"] = disasm("GameMasterDice", "onResume")
+fam2["gm_clinit"] = disasm("GameMasterDice", "<clinit>")
+fam2["rr_showDetails"] = disasm("RollResult", "showDetails")
+fam2["rr_toString"] = disasm("RollResult", "toString")
+fam2["rra_getView"] = disasm("RollResultAdapter", "getView")
+fam2["ds_getDiceSet"] = disasm("DiceSet", "getDiceSet")
+fam2["ds_roll"] = disasm("DiceSet;", "roll")
+fam2["ds_toString"] = disasm("DiceSet;", "toString")
+fam2["std_roll"] = disasm("StandardDiceSet", "roll")
+fam2["snp_getRealValue"] = disasm("SignedNumberPicker", "getRealValue")
+fam2["snp_init"] = disasm("SignedNumberPicker", "init")
+out2 = OUT / "S191_GMDICE_GAMEPLAY_DISASM.json"
+out2.write_text(json.dumps(fam2, indent=1))
+print("WROTE", out2)
