+#!/usr/bin/env python3
+"""s191_verify.py — S191 gmdice COMPLETE-GAMEPLAY verification battery.
+
+Laws under test (F-NEW-601/602/603/604/605):
+  E1 gmdice determinism: 3 identical runs (rc=0, frame SHA equality) with
+     the full tap script 3 rolls + row tap -> details dialog.
+  E2 gmdice semantic rows: [S191-ARRAYADAPTER] getView texts == the app's
+     own DiceSet.toString() lines (real DEX), 3 rows materialized.
+  E3 regression: headingcalculator still rc=0 REAL_APP_CONTENT.
+  E4 regression: chessclock single tap still ticks (SETTEXT 9:5x).
+Evidence: evidence/s191_gmdice/S191_GMDICE_COMPLETE.json
+"""
+import hashlib
+import json
+import re
+import subprocess
+import time
+from pathlib import Path
+
+BASE = Path("/home/z/my-project")
+BIN = BASE / "work/repo/miniandroid/build/miniandroid"
+OUT = BASE / "work/run/s191"
+EVID = BASE / "work/repo/evidence/s191_gmdice"
+STORE = OUT / "store_gmdice"
+VERDICT_RE = re.compile(r"FRAME_ANALYSIS state=(\S+)")
+
+TAPS_ROLLS = ["581,1846@8", "116,1846@14", "348,1846@20"]      # 1d6, 3D20, 1d20
+TAPS_FULL = TAPS_ROLLS + ["150,65@30"]                          # + row-2 tap
+
+
+def sha16(p):
+    return hashlib.sha256(Path(p).read_bytes()).hexdigest()[:16]
+
+
+def run(tag, taps, frames=46, max_seconds=150):
+    rundir = OUT / tag
+    console = OUT / f"{tag}_console.log"
+    cmd = [str(BIN), "run", "--execution-mode", "real-dalvik",
+           "--data-root", str(STORE), "-o", str(rundir),
+           "--max-seconds", str(max_seconds), "--frames", str(frames),
+           "--trace", "--package", "de.duenndns.gmdice"]
+    for t in taps:
+        cmd += ["--tap", t]
+    t0 = time.time()
+    with open(console, "w") as cf:
+        r = subprocess.run(cmd, stdout=cf, stderr=subprocess.STDOUT,
+                           timeout=max_seconds + 90)
+    wall = round(time.time() - t0, 1)
+    text = console.read_text(errors="replace")
+    faces = {}
+    for f in sorted((rundir / "frames").glob("frame_*")):
+        m = re.search(r"frame_(\d+)", f.name)
+        if m:
+            faces[int(m.group(1))] = sha16(f)
+    row_texts = re.findall(r'\[S191-ARRAYADAPTER\] getView pos=(\d+) row=o\d+ text="([^"]*)"', text)
+    return {
+        "tag": tag, "rc": r.returncode, "wall_s": wall,
+        "verdict": VERDICT_RE.findall(text)[-1] if VERDICT_RE.findall(text) else None,
+        "n_frame_shas": len(faces),
+        "frame_shas": faces,
+        "list_item_click": len(re.findall(r"LIST_ITEM_CLICK", text)),
+        "dialog_shown": len(re.findall(r"\[DIALOG-DECOR\]", text)),
+        "adapter_inits": len(re.findall(r"\[S191-ARRAYADAPTER\] init ", text)),
+        "adapter_adds": len(re.findall(r"\[S191-ARRAYADAPTER\] add ", text)),
+        "setlistadapter": len(re.findall(r"\[S191-SETLISTADAPTER\]", text)),
+        "listview_adopted": len(re.findall(r"getListView ADOPTED", text)),
+        "getview_texts": row_texts,
+    }
+
+
+def main():
+    EVID.mkdir(parents=True, exist_ok=True)
+    results = {"session": "S191", "binary_sha16": sha16(BIN),
+               "law_set": "F-NEW-601/602/603/604/605",
+               "runs": [], "regressions": []}
+
+    # ── E1: determinism 3x with the FULL gameplay tap script ──────────
+    for tag in ("s191_A", "s191_B", "s191_C"):
+        results["runs"].append(run(tag, TAPS_FULL))
+    a, b, c = results["runs"]
+    shas_a = a["frame_shas"]
+    a_vs_b = sum(1 for k in shas_a if k in b["frame_shas"] and
+                 b["frame_shas"][k] == shas_a[k])
+    a_vs_c = sum(1 for k in shas_a if k in c["frame_shas"] and
+                 c["frame_shas"][k] == shas_a[k])
+    results["determinism"] = {
+        "frames_compared": len(shas_a), "A_vs_B_identical": a_vs_b,
+        "A_vs_C_identical": a_vs_c,
+        "byte_identical_3x": a_vs_b == len(shas_a) == a_vs_c,
+        "final_frame_sha16": shas_a.get(max(shas_a)) if shas_a else None,
+    }
+
+    # ── E3/E4: regressions (existing stores) ───────────────────────────
+    hc_store = BASE / "work/run/s191/store_heading"
+    if not hc_store.exists():
+        subprocess.run([str(BIN), "install",
+                        str(BASE / "upload/canonical_apks_restored/org.debian.eugen.headingcalculator_1.apk"),
+                        "--data-root", str(hc_store)], capture_output=True)
+    cmd = [str(BIN), "run", "--execution-mode", "real-dalvik",
+           "--data-root", str(hc_store), "-o", str(OUT / "reg_heading"),
+           "--max-seconds", "60", "--frames", "12", "--trace",
+           "--package", "org.debian.eugen.headingcalculator"]
+    with open(OUT / "reg_heading_console.log", "w") as cf:
+        rh = subprocess.run(cmd, stdout=cf, stderr=subprocess.STDOUT, timeout=150)
+    htext = (OUT / "reg_heading_console.log").read_text(errors="replace")
+    results["regressions"].append({
+        "app": "headingcalculator", "rc": rh.returncode,
+        "verdict": VERDICT_RE.findall(htext)[-1] if VERDICT_RE.findall(htext) else None,
+        "th_gs_present": bool(re.search(r"TH=343", htext)) or "343" in htext,
+    })
+
+    cc_store = BASE / "work/run/s191/store_chessclock"
+    if not cc_store.exists():
+        subprocess.run([str(BIN), "install",
+                        str(BASE / "upload/canonical_apks_restored/com.chessclock.android_29.apk"),
+                        "--data-root", str(cc_store)], capture_output=True)
+    cmd = [str(BIN), "run", "--execution-mode", "real-dalvik",
+           "--data-root", str(cc_store), "-o", str(OUT / "reg_chessclock"),
+           "--max-seconds", "60", "--frames", "24", "--trace",
+           "--package", "com.chessclock.android", "--tap", "540,477"]
+    with open(OUT / "reg_chessclock_console.log", "w") as cf:
+        rc = subprocess.run(cmd, stdout=cf, stderr=subprocess.STDOUT, timeout=150)
+    ctext = (OUT / "reg_chessclock_console.log").read_text(errors="replace")
+    results["regressions"].append({
+        "app": "chessclock", "rc": rc.returncode,
+        "verdict": VERDICT_RE.findall(ctext)[-1] if VERDICT_RE.findall(ctext) else None,
+        "ticking": bool(re.search(r'text="9:5\d"', ctext)),
+    })
+
+    dest = EVID / "S191_GMDICE_COMPLETE.json"
+    dest.write_text(json.dumps(results, indent=1))
+    print("WROTE", dest)
+    print(json.dumps(results["determinism"], indent=1))
+    for r in results["runs"]:
+        print(r["tag"], "rc", r["rc"], r["verdict"], "clicks", r["list_item_click"],
+              "dialogs", r["dialog_shown"], "adds", r["adapter_adds"])
+    for r in results["regressions"]:
+        print("REG", r["app"], "rc", r["rc"], r["verdict"],
+              "tick/th" , r.get("ticking", r.get("th_gs_present")))
+
+
+if __name__ == "__main__":
+    main()
